/**
 * Boost index — AUTO-GENERATED, DO NOT EDIT.
 *
 * Every enhancement the game can name, keyed by the spelling the game client
 * prints for it, pointing at the contract section that describes it.
 * Built from boostsets.json + boosts/** by scripts/convert-boost-index.cjs.
 *
 * Regenerate: node scripts/convert-boost-index.cjs --dataset homecoming
 */

export interface BoostIndexEntry {
  /** Which contract section describes this enhancement, or 'unclassified'. */
  kind: 'io-set' | 'common-io' | 'origin' | 'special' | 'unclassified';
  /** io-set: the `io-sets` set id and 1-based piece number, and whether attuned. */
  set?: string;
  piece?: number;
  attuned?: boolean;
  /** special: the family category tag a slotted piece carries, and the entry id. */
  family?: string;
  id?: string;
  /** origin: the tier and the origins whose characters may slot it. */
  tier?: 'TO' | 'DO' | 'SO';
  origins?: string[];
  /** common-io: the crafted level, or null for the level-scaling template. */
  level?: number | null;
  /** common-io and origin: the planner stats the record enhances. */
  stats?: string[];
}

export interface BoostIndexData {
  dataset: string;
  entries: Record<string, BoostIndexEntry>;
  /** The pickable common-IO types, one per boost type the crafted family carries. */
  commonIoTypes: string[];
  /**
   * Pickable common-IO type -> the level-scaling record the game names it by.
   *
   * The template, not one of its nine levelled siblings, because every caller
   * carries the level on its own axis. `Fly` is `Crafted_Fly`, and `Slow` is
   * `Crafted_Snare` — neither is the planner stat with a prefix stuck on it, which
   * is what a hand-written table assumed twice.
   */
  commonIo: Record<string, string>;
}

